esqlQuery.esql:
FROM logs-vercel.logs.otel-default
// Restrict to sources that produce genuine HTTP responses (lambda/edge); static/firewall/redirect/external are covered by other rules
// Exclude deployment.environment.name filter or add preview back in if you want to monitor non-production traffic
| WHERE deployment.environment.name == "production"
    AND vercel.log.source IN ("lambda", "edge")
    // -1 means the function crashed before returning any response; excluded here, tracked by the crash-rate rule instead
    AND http.response.status_code != -1
| STATS
    total = COUNT(*),
    errors = COUNT(*) WHERE http.response.status_code >= 500
  BY vercel.log.source
// Minimum sample size to avoid noisy alerts on low-traffic sources; raise this for high-traffic production apps
| WHERE total > 20
// TO_DOUBLE(...) avoids integer division truncation before the percentage multiplication
| EVAL error_rate_pct = ROUND(TO_DOUBLE(errors) / total * 100.0, 2)
// Alert threshold: the spec's healthy baseline is <1%; set slightly above that to reduce noise from brief blips.
// Tighten to 1.0 for stricter SLA-aligned alerting, or raise for noisier/lower-traffic deployments.
| WHERE error_rate_pct > 2.0
| SORT error_rate_pct DESC
| LIMIT 10
